ALTER TABLE "Clients" ADD "OnboardingCompleted" boolean NOT NULL DEFAULT FALSE;
UPDATE "Clients" SET "OnboardingCompleted" = TRUE;
ALTER TABLE "MealPlans" DROP CONSTRAINT "FK_MealPlans_Clients_ClientId";
DROP INDEX "IX_MealPlans_ClientId";
ALTER TABLE "MealPlans" ALTER COLUMN "ClientId" TYPE uuid;
ALTER TABLE "MealPlans" ALTER COLUMN "ClientId" DROP NOT NULL;
ALTER TABLE "MealPlans" ADD "Title" character varying(200) NOT NULL DEFAULT 'Meal plan';
ALTER TABLE "MealPlans" ADD "IsTemplate" boolean NOT NULL DEFAULT FALSE;
ALTER TABLE "MealPlans" ADD "Status" character varying(20) NOT NULL DEFAULT 'Draft';
ALTER TABLE "MealPlans" ADD "RowVersion" bytea NOT NULL DEFAULT gen_random_bytes(8);
ALTER TABLE "MealPlans" ADD "IsDeleted" boolean NOT NULL DEFAULT FALSE;
ALTER TABLE "MealPlans" ADD "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
WITH ranked AS (SELECT "Id", row_number() OVER (PARTITION BY "TenantId", "ClientId" ORDER BY "CreatedAt" DESC, "Id") AS rn FROM "MealPlans" WHERE "ClientId" IS NOT NULL) UPDATE "MealPlans" p SET "Status" = CASE WHEN ranked.rn = 1 THEN 'Active' ELSE 'Archived' END FROM ranked WHERE p."Id" = ranked."Id";
CREATE INDEX "IX_MealPlans_ClientId" ON "MealPlans" ("ClientId");
CREATE UNIQUE INDEX "IX_MealPlans_TenantId_ClientId" ON "MealPlans" ("TenantId", "ClientId") WHERE "Status" = 'Active' AND "ClientId" IS NOT NULL AND "IsTemplate" = FALSE AND "IsDeleted" = FALSE;
ALTER TABLE "MealPlans" ADD CONSTRAINT "FK_MealPlans_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE RESTRICT;
CREATE TABLE "Meals" ("Id" uuid NOT NULL, "MealPlanId" uuid NOT NULL, "Name" character varying(200) NOT NULL, "Time" time without time zone, "Calories" numeric(8,2) NOT NULL, "Protein" numeric(8,2) NOT NULL, "Carbs" numeric(8,2) NOT NULL, "Fat" numeric(8,2) NOT NULL, CONSTRAINT "PK_Meals" PRIMARY KEY ("Id"), CONSTRAINT "FK_Meals_MealPlans_MealPlanId" FOREIGN KEY ("MealPlanId") REFERENCES "MealPlans" ("Id") ON DELETE CASCADE);
CREATE INDEX "IX_Meals_MealPlanId" ON "Meals" ("MealPlanId");
CREATE TABLE "WorkoutLogs" ("Id" uuid NOT NULL, "TenantId" uuid NOT NULL, "ClientId" uuid NOT NULL, "ProgramExerciseId" uuid NOT NULL, "PerformedOn" date NOT NULL, "SetNumber" integer NOT NULL, "Reps" integer NOT NULL, "WeightKg" numeric(7,2) NOT NULL, "PerformedAt" timestamp with time zone NOT NULL, "CreatedAt" timestamp with time zone NOT NULL, "IsDeleted" boolean NOT NULL DEFAULT FALSE, CONSTRAINT "PK_WorkoutLogs" PRIMARY KEY ("Id"), CONSTRAINT "FK_WorkoutLogs_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE RESTRICT, CONSTRAINT "FK_WorkoutLogs_ProgramExercises_ProgramExerciseId" FOREIGN KEY ("ProgramExerciseId") REFERENCES "ProgramExercises" ("Id") ON DELETE RESTRICT, CONSTRAINT "FK_WorkoutLogs_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "IX_WorkoutLogs_TenantId_ClientId_ProgramExerciseId_PerformedOn_SetNumber" ON "WorkoutLogs" ("TenantId", "ClientId", "ProgramExerciseId", "PerformedOn", "SetNumber");
CREATE INDEX "IX_WorkoutLogs_TenantId_ClientId_PerformedAt" ON "WorkoutLogs" ("TenantId", "ClientId", "PerformedAt");
